export function serviceCommand(input,session,ctx){
 const {nodes,links,isOffline,byId}=ctx,n=session?.node;if(!n)return 'No connection. Equip 1 Console or 2 LAN, aim at a service port, and press E.';
 if(isOffline(n))return n.id+' is offline. No response from the simulated device.';
 const command=input.trim().toLowerCase();
 if(command==='help')return 'help\nshow system\nshow interfaces\nshow links\nshow storage\nping DEVICE-ID\nclear\nTraining commands; vendor operating systems are not emulated.';
 if(command==='show system'||command==='show version')return `${n.id}\n${n.model}\nRack ${n.rack} · ${n.units??'—'}U\nPower: ON\nSession: ${session.mode}\nSimulated service session`;
 if(command==='show interfaces'||command==='show links')return n.ports.map(p=>`${p.name.padEnd(22)} ${p.medium.padEnd(14)} ${p.service?(session.port===p?'LAPTOP ATTACHED':'AVAILABLE'):p.link?(p.link.disabled||p.link.unplugged?'DOWN':'UP'):'NO CABLE'}${p.link?' → '+(p.link.a===n.id?p.link.b:p.link.a):''}`).join('\n');
 if(command==='show storage'){const sanLinks=links.filter(l=>l.kind==='storage'&&(l.a===n.id||l.b===n.id)).map(l=>`${l.a} ↔ ${l.b}: ${l.disabled||l.unplugged?'DOWN':'UP'}`),c={nodes,byId,links},vols=n.type==='storage'?arrayVolumes(n,c).map(v=>`${v.volume} → ${v.host||'unmapped'}: ${String(v.state).toUpperCase()} · ${v.reason}`):['server','gpu'].includes(n.type)?hostVolumes(n,c).map(v=>`${v.array} / ${v.volume} (${v.access||'—'}): ${v.state.toUpperCase()} · ${v.reason}`):[];return [...sanLinks,...(vols.length?['Volumes:',...vols]:[])].join('\n')||'No SAN links or mapped volumes on this device.';}
 if(command.startsWith('ping ')){const destination=input.trim().split(/\s+/)[1]?.toUpperCase();if(!byId[destination])return 'Unknown device. Use its topology name, for example CORE-A or SERVER-01.';const visited=new Set([n.id]),q=[n.id];while(q.length){const id=q.shift();if(isOffline(byId[id]))continue;if(id===destination)return `Graph probe ${destination}: REACHABLE\nSynthetic result; no ICMP or IP configuration is emulated.`;for(const l of links){if(l.kind!=='application'||l.disabled||l.unplugged)continue;const other=l.a===id?l.b:l.b===id?l.a:null;if(other&&!visited.has(other)){visited.add(other);q.push(other);}}}return `Graph probe ${destination}: NO APPLICATION PATH`;}
 return 'Unknown command. Type help.';
}
